import { PlaneGeometry, MeshBasicNodeMaterial, Mesh, DoubleSide, Vector3 } from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // Geometry matching atlas source rect aspect ratio 512:320 = 1.6
  const width = 1.6;
  const height = width / (512 / 320); // = 1.0
  const geometry = new PlaneGeometry(width, height);

  // Texture loading
  const map = ctx.textureLoader.load(config.imageUrl);

  // Material – no lighting, double side for safety
  const material = new MeshBasicNodeMaterial({
    map,
    side: DoubleSide,
    transparent: true,
  });

  const mesh = new Mesh(geometry, material);

  // Scene placement
  const pos = config.scenePosition || { x: 1.25, y: 1.6, z: 0 };
  mesh.position.set(pos.x, pos.y, pos.z);
  if (config.sceneRotation) {
    mesh.rotation.set(config.sceneRotation.x, config.sceneRotation.y, config.sceneRotation.z);
  }
  if (config.sceneScale) {
    mesh.scale.set(config.sceneScale.x, config.sceneScale.y, config.sceneScale.z);
  }

  // Interactions
  mesh.userData.handlers = {};

  // Hover: subtle rise (preset "rise-in")
  let hoverTween = null;
  let clickTween = null;
  const originalY = mesh.position.y;

  mesh.userData.handlers.pointerover = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(mesh.position, {
      y: originalY + 0.15,
      duration: 0.3,
      ease: 'power3.out',
      overwrite: true,
    });
  };

  mesh.userData.handlers.pointerout = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(mesh.position, {
      y: originalY,
      duration: 0.3,
      ease: 'power3.out',
      overwrite: true,
    });
  };

  // Click: emit event and press-down effect
  mesh.userData.handlers.click = () => {
    if (clickTween) clickTween.kill();
    clickTween = gsap.to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
      yoyo: true,
      repeat: 1,
      onComplete: () => {
        clickTween = null;
      },
    });
    // Emit navigation event
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-pricing.select', {});
    }
  };

  // Data bindings – stored for parent consumption
  if (config.dataBindings) {
    mesh.userData.dataBindings = config.dataBindings;
  }

  // Apply cinematic primitives
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach(prim => {
      const primitiveFn = ctx.primitives?.[prim.name];
      if (primitiveFn) {
        primitiveFn(mesh, prim.params);
      } else {
        console.warn(`Primitive "${prim.name}" not found in ctx.primitives`);
      }
    });
  }

  // Cleanup
  mesh.userData.cleanup = () => {
    // Kill all GSAP tweens stored on mesh
    if (hoverTween) {
      hoverTween.kill();
      hoverTween = null;
    }
    if (clickTween) {
      clickTween.kill();
      clickTween = null;
    }
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
    // Remove event listeners (handlers are stored as references, no DOM listeners)
  };

  return mesh;
}
